  if(tool.type==='html-framer-manager')return `<div class="admin-tool"><b>${esc(tool.label||'HTML Frames')}</b><div class="msg">ZIP → isolated LOOM frame module. Packages are stored in the Instance Vault.</div><div data-html-framer-manager><div class="html-framer-empty">Loading HTML frames…</div></div></div>`;
