}
function globalToolHtml(tool,m){if(tool.type==='domain-landing-manager')return domainLandingToolHtml(tool,m);return ''}
function bindDomainLandingManagers(box){
  box.querySelectorAll('[data-domain-landing]').forEach(host=>{
    const mode=host.querySelector('[data-domain-mode]'),projectWrap=host.querySelector('[data-domain-project-wrap]'),project=host.querySelector('[data-domain-project]'),msg=host.querySelector('[data-domain-msg]');
    const sync=()=>{projectWrap.hidden=mode.value!=='project'};mode.addEventListener('change',sync);sync();
    host.querySelector('[data-domain-save]')?.addEventListener('click',async()=>{
      if(mode.value==='project'&&!project.value){msg.textContent='Choose a landing project first.';return}
      const label=mode.value==='project'?(project.options[project.selectedIndex]?.textContent||project.value):'LOOM Home';
      if(!confirm(`Make the LOOM installation base URL open ${label}?\n\nLOOM Home will remain available at /home/.`))return;
      msg.textContent='Saving routing…';
      try{globalState=await post({action:'domain-landing-save',mode:mode.value,project:project.value});renderGlobalModules();msg.textContent=''}catch(e){msg.textContent=e.message}
    });
    host.querySelector('[data-domain-home]')?.addEventListener('click',async()=>{
      if(!confirm('Restore LOOM Home as the installation base landing page?'))return;
      msg.textContent='Restoring LOOM Home…';
      try{globalState=await post({action:'domain-landing-home'});renderGlobalModules()}catch(e){msg.textContent=e.message}
    });
  })
}
function renderGlobalModules(){const box=$('#globalModules'),mods=globalState?.modules||[];box.innerHTML=mods.map(m=>{const fields=m.admin_settings?.fields||[];return `<section class="module" data-module="${esc(m.actionId)}"><div class="eyebrow">GLOBAL · ${esc(m.actionId)}</div><h2>${esc(m.admin_settings?.title||m.name)}</h2><div class="desc">${esc(m.admin_settings?.description||m.description)}</div>${fields.map(f=>fieldHtml(f,m.values?.[f.id]??m.defaults?.[f.id])).join('')}${(m.admin_settings?.tools||[]).map(t=>globalToolHtml(t,m)).join('')}${fields.length?`<div class="buttons"><button class="save" data-global-save>Save LOOM Setting</button><button class="reset" data-global-reset>Reset LOOM Default</button></div>`:''}<div class="msg" data-msg></div></section>`}).join('');box.querySelectorAll('input[type=range]').forEach(el=>el.oninput=()=>{const f=mods.flatMap(x=>x.admin_settings?.fields||[]).find(x=>x.id===el.dataset.field),out=box.querySelector(`[data-value="${CSS.escape(el.dataset.field)}"]`);if(out)out.textContent=el.value+(f?.unit||'')});bindConditionalFields(box);bindDomainLandingManagers(box);box.querySelectorAll('[data-global-save]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module'),m=mods.find(x=>x.actionId===card.dataset.module),vals={};for(const f of m.admin_settings.fields){const el=card.querySelector(`[data-field="${CSS.escape(f.id)}"]`);vals[f.id]=readAdminField(el,f)}try{globalState=await post({action:'global-save',moduleId:card.dataset.module,values:vals});renderGlobalModules();await refreshAdminCube()}catch(e){card.querySelector('[data-msg]').textContent=e.message}});box.querySelectorAll('[data-global-reset]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module');try{globalState=await post({action:'global-reset',moduleId:card.dataset.module});renderGlobalModules();await refreshAdminCube()}catch(e){card.querySelector('[data-msg]').textContent=e.message}})}
let adminCubeCleanup=null;async function refreshAdminCube(){try{const g=await LoomBrand.fetchSettings('../api'),bc=LoomBrand.brandConfig(g);adminCubeCleanup?.();adminCubeCleanup=LoomBrand.mountCube($('#adminCube'),{size:58,path:bc.path,speed:bc.speed,animate:bc.animate})}catch{}}
