async function htmlFramerRequest(action,opts={}){
  const project=$('#project').value;
  if(opts.file){
    const fd=new FormData();fd.append('action',action);fd.append('project',project);fd.append('clientId',identity.clientId);fd.append('zip',opts.file,opts.file.name);
    if(opts.entrypoint)fd.append('entrypoint',opts.entrypoint);if(opts.replaceId)fd.append('replaceId',opts.replaceId);
    const r=await fetch('../api/html-framer.php',{method:'POST',body:fd,cache:'no-store'}),j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'HTML Framer request failed');return j
  }
  if(action==='list'){
    const r=await fetch(`../api/html-framer.php?action=list&project=${encodeURIComponent(project)}&clientId=${encodeURIComponent(identity.clientId)}&_=${Date.now()}`,{cache:'no-store'}),j=await r.json();
    if(!r.ok||!j.ok)throw new Error(j.error||'HTML Framer request failed');return j
  }
  const r=await fetch('../api/html-framer.php',{method:'POST',headers:{'Content-Type':'application/json'},cache:'no-store',body:JSON.stringify({action,project,clientId:identity.clientId,...opts})});
  const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'HTML Framer request failed');return j
}
function htmlFramerAnalysisHtml(a){
  if(!a)return '';
  const size=Math.round((a.totalBytes||0)/1024);
  const repairs=(a.repairs||[]).length,missing=(a.missingRefs||[]).length,warns=[...(a.warnings||[])];
  if(missing)warns.push(`${missing} local reference${missing===1?'':'s'} could not be resolved automatically.`);
  const reader=a.actionReader||{},readerText=`${esc(reader.trackableCount||0)} trackable UI action${Number(reader.trackableCount||0)===1?'':'s'} · ${esc(reader.functionCandidateCount||0)} JS function candidate${Number(reader.functionCandidateCount||0)===1?'':'s'} · ${esc(reader.listenerEventCount||0)} listener registration${Number(reader.listenerEventCount||0)===1?'':'s'}`;
  return `<div class="html-framer-analysis"><b>${esc(a.fileCount||0)} files · ${esc(a.cssCount||0)} CSS · ${esc(a.jsCount||0)} JS · ${esc(size)} KB</b><br><b>Action Reader:</b> ${readerText}. ${(reader.functionCandidateCount||0)?'Function names are discovery hints; LOOM tracks observable user interactions without wrapping arbitrary foreign functions. ':''}${repairs?`${esc(repairs)} safe path repair${repairs===1?'':'s'} detected. `:''}${(a.autoAttachCss||[]).length?`${esc(a.autoAttachCss.length)} CSS root${a.autoAttachCss.length===1?'':'s'} will be auto-attached. `:''}${(a.autoAttachJs||[]).length?`${esc(a.autoAttachJs.length)} JS root${a.autoAttachJs.length===1?'':'s'} will be auto-attached.`:''}${warns.length?`<div class="html-framer-warnings">${warns.slice(0,8).map(x=>esc(x)).join('<br>')}</div>`:''}</div>`
}
function htmlFramerRows(frames){
  if(!frames?.length)return '<div class="html-framer-empty">No HTML frame modules yet. Drop a ZIP above to create one.</div>';
  return `<div class="html-framer-list">${frames.map((f,i)=>`<div class="html-framer-row" data-hf-id="${esc(f.id)}"><div class="html-framer-row-head"><label class="field-check"><input type="checkbox" data-hf-enabled ${f.enabled!==false?'checked':''}><span>Live</span></label><label class="field-check"><input type="checkbox" data-hf-track ${f.actionReaderEnabled!==false?'checked':''}><span>Track actions</span></label><input class="html-framer-row-title" data-hf-title value="${esc(f.title||'HTML Frame')}"><div class="buttons" style="margin:0"><button class="reset" data-hf-move="up" ${i===0?'disabled':''}>↑</button><button class="reset" data-hf-move="down" ${i===frames.length-1?'disabled':''}>↓</button><button class="danger" data-hf-delete>Delete</button></div></div><div class="html-framer-meta"><code>${esc(f.id)}</code> · entry <code>${esc(f.entrypoint||'')}</code> · ${esc(f.fileCount||0)} files · revision ${esc(f.revision||1)}${f.zipName?` · ${esc(f.zipName)}`:''} · Action Reader ${f.actionReaderEnabled===false?'off':`${esc(f.actionReader?.trackableCount||0)} cataloged`}</div><div class="html-framer-controls"><div><label style="font-size:9px;font-weight:900;color:#58705f">Frame height · <span data-hf-height-value>${esc(f.height||520)}px</span></label><input data-hf-height type="range" min="200" max="1600" step="10" value="${esc(f.height||520)}" style="width:100%"></div><button class="save" data-hf-save>Save Frame</button></div>${(f.warnings||[]).length|| (f.missingRefs||[]).length?`<div class="html-framer-warnings">${[...(f.warnings||[]),...((f.missingRefs||[]).slice(0,5).map(x=>`Unresolved: ${x.from} → ${x.raw}`))].slice(0,8).map(x=>esc(x)).join('<br>')}</div>`:''}</div>`).join('')}</div>`
}
async function htmlFramerLoad(node){
  try{const data=await htmlFramerRequest('list');node._hfData=data;htmlFramerRender(node)}catch(e){node.innerHTML=`<div class="html-framer-warnings">${esc(e.message)}</div>`}
}
function htmlFramerRender(node){
  const data=node._hfData||{frames:[]},a=node._hfAnalysis||null,candidates=a?.htmlCandidates||[],needs=!!a?.needsEntrypoint;
  node.innerHTML=`<div class="html-framer-drop" data-hf-drop><b>Drop one HTML package ZIP here</b><div class="msg">LOOM preserves valid links, discovers dependencies and auto-attaches orphan CSS/JS roots.</div><input data-hf-file type="file" accept=".zip,application/zip">${needs?`<div class="field"><label>Multiple HTML files found · choose the entrypoint</label><select data-hf-entry>${candidates.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></div>`:''}<div class="buttons"><button class="secondary" data-hf-analyze>Analyze ZIP</button><button class="save" data-hf-publish ${!node._hfFile?'disabled':''}>${needs?'Publish Selected Entrypoint':'Publish Frame Module'}</button></div>${htmlFramerAnalysisHtml(a)}</div>${htmlFramerRows(data.frames||[])}`;
  const drop=node.querySelector('[data-hf-drop]'),fileInput=node.querySelector('[data-hf-file]');
  const choose=async file=>{if(!file)return;node._hfFile=file;try{const r=await htmlFramerRequest('analyze',{file});node._hfAnalysis=r.analysis;htmlFramerRender(node)}catch(e){node._hfAnalysis={warnings:[e.message]};htmlFramerRender(node)}};
  fileInput.onchange=()=>choose(fileInput.files?.[0]);
  drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');const f=e.dataTransfer.files?.[0];if(f)choose(f)};
  node.querySelector('[data-hf-analyze]').onclick=()=>choose(node._hfFile||fileInput.files?.[0]);
  node.querySelector('[data-hf-publish]').onclick=async()=>{const file=node._hfFile;if(!file)return;const entry=node.querySelector('[data-hf-entry]')?.value||node._hfAnalysis?.entrypoint||'';try{const r=await htmlFramerRequest('upload',{file,entrypoint:entry});if(r.needsEntrypoint){node._hfAnalysis=r.analysis;htmlFramerRender(node);return}node._hfFile=null;node._hfAnalysis=null;node._hfData=r;htmlFramerRender(node)}catch(e){alert(e.message)}};
  node.querySelectorAll('[data-hf-height]').forEach(el=>el.oninput=()=>{el.closest('.html-framer-row').querySelector('[data-hf-height-value]').textContent=`${el.value}px`});
  node.querySelectorAll('[data-hf-save]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-hf-id]');try{node._hfData=await htmlFramerRequest('update',{frameId:row.dataset.hfId,title:row.querySelector('[data-hf-title]').value,enabled:row.querySelector('[data-hf-enabled]').checked,actionReaderEnabled:row.querySelector('[data-hf-track]').checked,height:Number(row.querySelector('[data-hf-height]').value)});htmlFramerRender(node)}catch(e){alert(e.message)}});
  node.querySelectorAll('[data-hf-move]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-hf-id]');try{node._hfData=await htmlFramerRequest('move',{frameId:row.dataset.hfId,direction:btn.dataset.hfMove});htmlFramerRender(node)}catch(e){alert(e.message)}});
  node.querySelectorAll('[data-hf-delete]').forEach(btn=>btn.onclick=async()=>{const row=btn.closest('[data-hf-id]');if(!confirm('Delete this HTML frame module and its stored ZIP/files?'))return;try{node._hfData=await htmlFramerRequest('delete',{frameId:row.dataset.hfId});htmlFramerRender(node)}catch(e){alert(e.message)}});
}
function bindHtmlFramerManagers(scope){scope.querySelectorAll('[data-html-framer-manager]').forEach(node=>htmlFramerLoad(node))}

function renderModuleControl(){const list=$('#moduleControlList'),q=($('#moduleControlSearch')?.value||'').trim().toLowerCase(),catalog=state?.module_catalog||[];if(!list)return;const rows=catalog.filter(m=>!q||[m.name,m.actionId,m.source,m.scope].some(v=>String(v||'').toLowerCase().includes(q)));list.innerHTML=rows.length?rows.map(m=>{const mobileSupported=m.mobileVisibilitySupported!==false&&m.scope==='project';return `<div class="module-control-row" data-control-module="${esc(m.actionId)}" data-control-scope="${esc(m.scope)}"><label class="module-control-switch" title="${m.enabled?'Disable':'Enable'} ${esc(m.name)}"><input class="module-enabled-toggle" type="checkbox" ${m.enabled?'checked':''} ${m.locked?'disabled':''}><span></span></label><div class="module-control-name"><strong>${esc(m.name)}</strong><small>${esc(m.actionId)} · ${esc(m.description||'')}</small></div><span class="module-control-badge">${esc(m.scope)} · ${esc(m.source)}</span>${mobileSupported?`<label class="module-mobile-control" title="Do not load this module when the project viewport is mobile-width (767px or narrower)."><input class="module-mobile-toggle" type="checkbox" ${m.hideOnMobile?'checked':''}><span>Hide on mobile</span></label>`:`<span class="module-mobile-control disabled" title="Responsive visibility is controlled per project module.">Desktop + mobile</span>`}<span class="module-control-status">${m.enabled?'Enabled':'Disabled'}</span></div>`}).join(''):'<div class="empty" style="margin:12px">No matching modules.</div>';list.querySelectorAll('[data-control-module] .module-enabled-toggle').forEach(el=>el.onchange=async()=>{const row=el.closest('[data-control-module]'),status=row.querySelector('.module-control-status');status.textContent='Saving…';el.disabled=true;try{const d=await post({action:'module-toggle',project:$('#project').value,moduleId:row.dataset.controlModule,scope:row.dataset.controlScope,enabled:el.checked});if(row.dataset.controlScope==='global'){globalState=d;state=aw