function renderModules(){const box=$('#modules'),mods=state?.modules||[];box.innerHTML=mods.map(m=>{const fields=m.admin_settings?.fields||[];return `<section class="module" data-module="${esc(m.actionId)}"><div class="eyebrow">${m.source==='core-project'?'CORE PROJECT · ':''}${esc(m.order)} · ${esc(m.actionId)}</div><h2>${esc(m.admin_settings?.title||m.name)}</h2><div class="desc">${esc(m.admin_settings?.description||m.description)}</div>${fields.map(f=>fieldHtml(f,m.values?.[f.id]??m.defaults?.[f.id])).join('')}${(m.admin_settings?.tools||[]).map(t=>toolHtml(t,m)).join('')}${fields.length?`<div class="buttons"><button class="save" data-save>Save</button><button class="reset" data-reset>Reset defaults</button></div>`:''}<div class="msg" data-msg></div></section>`}).join('');box.querySelectorAll('input[type=range]').forEach(el=>el.oninput=()=>{const f=mods.flatMap(x=>x.admin_settings?.fields||[]).find(x=>x.id===el.dataset.field),out=box.querySelector(`[data-value="${CSS.escape(el.dataset.field)}"]`);if(out)out.textContent=el.value+(f?.unit||'')});bindConditionalFields(box);bindHtmlFramerManagers(box);bindShowcaseManagers(box);box.querySelectorAll('[data-save]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module'),m=mods.find(x=>x.actionId===card.dataset.module),vals={};for(const f of m.admin_settings.fields){const el=card.querySelector(`[data-field="${CSS.escape(f.id)}"]`);vals[f.id]=readAdminField(el,f)}try{state=await post({action:'save',project:$('#project').value,moduleId:card.dataset.module,values:vals});renderModules()}catch(e){card.querySelector('[data-msg]').textContent=e.message}});box.querySelectorAll('[data-reset]').forEach(btn=>btn.onclick=async()=>{const card=btn.closest('.module');try{state=await post({action:'reset',project:$('#project').value,moduleId:card.dataset.module});renderModules()}catch(e){card.querySelector('[data-msg]').textContent=e.message}});box.querySelectorAll('[data-config-preset]').forEach(btn=>btn.onclick=async()=>{c