d===cid)||{};return `<tr><td><code>${esc(cid)}</code></td><td><code>${esc(p.profileId||'—')}</code></td><td>${esc(p.username||'—')}</td><td>${esc(fmt(p.createdAt))}</td><td>${esc(fmt(p.updatedAt))}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty">No linked clients.</div>'}${activity.latestClientMeta?`<div class="detail-grid"><div class="info"><b>Language</b>${esc(activity.latestClientMeta.language||'—')}</div><div class="info"><b>Timezone</b>${esc(activity.latestClientMeta.timezone||'—')}</div><div class="info"><b>Platform</b>${esc(activity.latestClientMeta.platform||'—')}</div><div class="info"><b>User Agent</b><code>${esc(activity.latestClientMeta.userAgent||'—')}</code></div></div>`:''}</div><div class="module" style="margin-top:14px"><div class="eyebrow">RECENT PROJECT ACTIVITY</div><h2>Sessions & actions</h2><div class="detail-grid"><div class="info"><b>First seen</b>${esc(fmt(activity.firstSeen))}</div><div class="info"><b>Last seen</b>${esc(fmt(activity.lastSeen))}</div><div class="info"><b>User actions</b>${esc(activity.userActionCount||0)}</div><div class="info"><b>Failures</b>${esc(activity.failureCount||0)}</div></div>${activity.recentSessions?.length?`<table class="ip-table"><thead><tr><th>Status</th><th>Session ID</th><th>Client</th><th>First</th><th>Last</th><th>Events</th></tr></thead><tbody>${activity.recentSessions.map(x=>`<tr><td>${esc(x.status)}</td><td><code>${esc(x.sessionId)}</code></td><td><code>${esc(x.clientId||'—')}</code></td><td>${esc(fmt(x.firstSeen))}</td><td>${esc(fmt(x.lastSeen))}</td><td>${esc(x.eventCount||0)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No session history in this project yet.</div>'}${activity.topActions?.length?`<div class="setup"><b>Top recorded actions</b><br>${activity.topActions.map(x=>`<code>${esc(x.actionId)}</code> × ${esc(x.count)}`).join(' &nbsp; · &nbsp; ')}</div>`:''}</div><div class="module" style="margin-top:14px"><div class="eyebrow">PROJECT IDENTITY · ${esc($('#project').value)}</div><h2>${esc(u.currentProjectIdentity?.effectiveUsername||u.currentProjectIdentity?.username||u.globalProfile?.username||'Project identity')}</h2><p>This project may inherit the LOOM-wide username/profile picture or override them.</p><div class="field"><label>LOOM-wide username</label><input id="editGlobalUsername" value="${esc(u.globalProfile?.username||'')}"></div><div class="buttons"><button class="save" id="saveGlobalUsername">Change LOOM Username</button></div><div class="field"><label>Project username override</label><input id="editUsername" value="${esc(u.currentProjectIdentity?.username||'')}"></div><div class="buttons"><button class="save" id="saveUsername">Use / Change Project Username</button><button class="secondary" id="useGlobalUsername">Use LOOM Username</button></div><div class="msg" id="userMsg"></div></div><div class="module" style="margin-top:14px"><div class="eyebrow">ALL PROJECT IDENTITIES</div><h2>${esc((u.projectIdentities||[]).length)} identities</h2>${u.projectIdentities?.length?`<table class="ip-table"><thead><tr><th>Project</th><th>Effective username</th><th>Username source</th><th>Avatar mode</th><th>Created</th><th>Updated</th></tr></thead><tbody>${u.projectIdentities.map(x=>`<tr><td>${esc(x.projectName||x.project)}</td><td><b>${esc(x.effectiveUsername||x.username||u.globalProfile?.username||'Not set')}</b></td><td>${esc(x.usernameMode==='global'?'LOOM profile':'Project override')}</td><td>${esc(x.avatarMode||'auto')}</td><td>${esc(fmt(x.createdAt))}</td><td>${esc(fmt(x.updatedAt))}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No project identities yet.</div>'}</div><div class="module" style="margin-top:14px"><div class="eyebrow">PERMANENT ACCOUNT CREDENTIALS</div><p>Email/password belong to the global LOOM account and unlock all of its project identities.</p>${u.registered?`<div class="field"><label>Email</label><input id="editEmail" type="email" value="${esc(account.email||'')}"></div><div class="buttons"><button class="save" id="saveEmail">Change Account Email</button></div><div class="field"><label>New password <span>current password is never shown</span></label><input id="editPassword" type="password" placeholder="8+ characters"></div><div class="buttons"><button class="danger" id="savePassword">Replace Account Password</button></div>`:'<div class="empty">This Guest Identity has no permanent account yet.</div>'}</div><div class="module" style="margin-top:14px"><div class="eyebrow">NETWORK METADATA</div><h2>Known IP addresses</h2><p>Captured by the server and visible to this user in their own Identity Details. Never used as authentication proof.</p>${u.ipHistory?.length?`<table class="ip-table"><thead><tr><th>IP</th><th>First seen</th><th>Last seen</th><th>Seen</th><th>Source</th></tr></thead><tbody>${u.ipHistory.map(x=>`<tr><td><code>${esc(x.ip||'—')}</code>${x.ipVersion?` <span class="pill">${esc(x.ipVersion)}</span>`:''}</td><td>${esc(fmt(x.firstSeen))}</td><td>${esc(fmt(x.lastSeen))}</td><td>${esc(x.seenCount)}</td><td>${esc(x.source||'—')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No IP captured yet.</div>'}</div><div class="moderation"><div class="eyebrow">PROJECT MODERATION · ${esc($('#project').value)}</div><h2>${st.banned?'Banned profile':'Profile allowed'}</h2><p>${st.banned?'The account still exists, but this identity cannot load or write to this project.':'This identity can access the project normally.'}</p><div class="buttons"><button class="${st.banned?'secondary':'danger'}" id="toggleBan">${st.banned?'Unban Profile':'Ban Profile'}</button></div>${st.banned?`<label class="switchline"><input id="includeData" type="checkbox" ${st.includeData?'checked':''}> Include this banned profile's retained data in project views</label><p style="margin-top:7px">Off by default. Turning it on does not restore access—it only makes retained historical data visible to project/admin views again.</p>`:''}</div>`;
  const msg=()=>$('#userMsg');$('#saveGlobalUsername').onclick=()=>mutateUser('update-global-username',{username:$('#editGlobalUsername').value},'Change this user’s LOOM-wide username?');$('#saveUsername').onclick=()=>mutateUser('update-username',{username:$('#editUsername').value},'Change this project username?');$('#useGlobalUsername').onclick=()=>mutateUser('use-global-username',{},'Make this project inherit the LOOM-wide username?');if(u.registered){$('#saveEmail').onclick=()=>mutateUser('update-email',{email:$('#editEmail').value},'Change this account email?');$('#savePassword').onclick=()=>mutateUser('set-password',{password:$('#editPassword').value},'Replace this user password and revoke their prior login sessions?')}$('#toggleBan').onclick=()=>mutateUser('set-ban',{banned:!st.banned},st.banned?'Unban this profile?':'Ban this profile from this project?');$('#includeData')?.addEventListener('change',async e=>{const ok=confirmPhrase(`${e.target.checked?'Include':'Hide'} this banned profile's retained data in project views?`);if(!ok){e.target.checked=!e.target.checked;return}try{const j=await usersPost({action:'set-include-data',subjectType:u.subjectType,subjectId:u.subjectId,includeData:e.target.checked,confirmPhrase:ok});renderUserDetail(j.user);await loadUsers()}catch(err){alert(err.message);e.target.checked=!e.target.checked}})
}
async function mutateUser(action,payload,message){const ok=confirmPhrase(message);if(!ok)return;try{const j=await usersPost({action,subjectType:selected.subjectType,subjectId:selected.subjectId,confirmPhrase:ok,...payload});renderUserDetail(j.user);await loadUsers()}catch(e){const m=$('#userMsg');if(m)m.textContent=e.message;else alert(e.message)}}
async function loadUserDetail(type,id){try{const j=await usersPost({action:'detail',subjectType:type,subjectId:id});renderUserDetail(j.user)}catch(e){$('#userDetail').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function identityGuestLabel(g){return `${g.status==='attached'?'Attached':'Guest'} · ${String(g.guestId||'').slice(0,18)}…`}
function renderIdentityList(){const q=($('#identitySearch')?.value||'').toLowerCase(),box=$('#identityList');if(!box)return;const rows=(identityState.guests||[]).filter(g=>!q||JSON.stringify(g).toLowerCase().includes(q));box.innerHTML=rows.map(g=>`<button class="user-row ${selectedGuestId===g.guestId?'active':''}" data-guest-id="${esc(g.guestId)}"><strong>${esc(identityGuestLabel(g))}</strong><small>${esc(g.status)} · ${esc(g.clientCount)} device/client${g.clientCount===1?'':'s'}${g.attachedUserId?` · → ${esc(g.attachedUserId)}`:''}</small><small>Seen ${esc(fmt(g.updatedAt))}</small></button>`).join('')||'<div class="empty">No Guest Identities match.</div>';box.querySelectorAll('[data-guest-id]').forEach(b=>b.onclick=()=>loadIdentityDetail(b.dataset.guestId))}
async function loadIdentities(){try{identityState=await identitiesPost({action:'list'});renderIdentityList()}catch(e){$('#identityList').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function renderIdentityDetail(d,users){const g=d.guest||{},a=d.activity||{},box=$('#identityDetail');selectedGuestId=g.guestId;renderIdentityList();const userOpts=(users||[]).map(u=>`<option value="${esc(u.userId)}">${esc(u.globalProfile?.username||u.email||u.userId)} · ${esc(u.email||u.userId)}</option>`).join('');box.innerHTML=`<div class="detail-head"><div><div class="eyebrow">GUEST IDENTITY</div><h2>${esc(g.guestId||'')}</h2><p>Status: <b>${esc(g.status||'')}</b>${g.attachedUserId?` · attached to <code>${esc(g.attachedUserId)}</code>`:''}${d.canonicalGuest?` · canonical target <code>${esc(d.canonicalGuest.guestId)}</code>`:''}</p></div></div><div class="detail-grid"><div class="info"><b>First seen</b><strong>${esc(fmt(g.createdAt))}</strong></div><div class="info"><b>Last seen</b><strong>${esc(fmt(g.updatedAt))}</strong></div><div class="info"><b>Clients / devices</b><strong>${esc(g.clientCount||0)}</strong></div><div class="info"><b>Snapshots</b><strong>${esc(g.snapshotCount||0)}</strong></div><div class="info"><b>Events</b><strong>${esc(a.eventCount||0)}</strong></div><div class="info"><b>Projects</b><strong>${esc(Object.keys(a.projects||{}).length)}</strong></div></div><div class="module" style="margin-top:14px"><div class="eyebrow">PROVENANCE</div><h2>Preserved activity</h2><p>Guest source history is retained even after attachment. Account attachment changes active ownership/access; it does not erase the Guest Identity.</p>${Object.keys(d.clients||{}).length?`<table class="ip-table"><thead><tr><th>Client</th><th>First seen</th><th>Last seen</th></tr></thead><tbody>${Object.entries(d.clients).map(([id,m])=>`<tr><td><code>${esc(id)}</code></td><td>${esc(fmt(m.firstSeen))}</td><td>${esc(fmt(m.lastSeen))}</td></tr>`).join('')}</tbody></table>`:''}</div><div class="module" style="margin-top:14px"><div class="eyebrow">SUPPORT RECOVERY</div><h2>Recovery tools</h2><p>Network, project, action-pattern, username, and timing signals can help find candidates, but are never proof of ownership and never trigger automatic merging.</p><div class="buttons"><button class="secondary" id="adminRecoveryCode" ${g.status!=='unattached'?'disabled':''}>Issue Recovery Code</button></div><div id="adminRecoveryOut" class="msg"></div></div><div class="module" style="margin-top:14px"><div class="eyebrow">ATTACH / CONVERT</div><h2>Permanent ownership</h2>${g.status==='attached'?`<div class="empty">Already attached to <code>${esc(g.attachedUserId||'')}</code>.</div>`:g.status==='merged'?`<div class="empty">This source Guest Identity is preserved as merge provenance. Perform ownership operations on canonical target <code>${esc(d.canonicalGuest?.guestId||g.mergedIntoGuestId||'')}</code>.</div>`:`<div class="field"><label>Attach to existing account</label><select id="attachUserId"><option value="">Choose permanent account…</option>${userOpts}</select></div><div class="buttons"><button class="save" id="attachGuest">Attach Guest History</button><button class="secondary" id="convertGuest">Create New Account from Guest</button></div><div class="field"><label>Merge into another unattached Guest Identity</label><select id="mergeTargetGuest"><option value="">Choose target Guest Identity…</option>${(identityState.guests||[]).filter(x=>x.guestId!==g.guestId&&x.status==='unattached').map(x=>`<option value="${esc(x.guestId)}">${esc(x.guestId)} · ${esc(fmt(x.updatedAt))}</option>`).join('')}</select></div><div class="buttons"><button class="secondary" id="mergeGuest">Merge Guest → Guest</button></div>`}<div id="identityMsg" class="msg"></div></div><div class="module" style="margin-top:14px"><div class="eyebrow">POSSIBLE RELATED GUESTS</div><h2>Manual evidence review</h2><p>These are search candidates only. LOOM never auto-attaches based on fuzzy evidence.</p><div class="identity-evidence">${(d.relatedGuests||[]).map(c=>`<div class="identity-evidence-row"><b>${esc(c.guest.guestId)}</b> · evidence score ${esc(c.evidenceScore)}<br>${c.signals.map(s=>`<span class="${s.weight==='strong'?'identity-strong':'identity-low'}">${esc(s.kind)} (${esc(s.weight)}): ${esc(s.detail)}</span>`).join('<br>')}</div>`).join('')||'<div class="empty">No related Guest Identity candidates found.</div>'}</div></div><div class="module" style="margin-top:14px"><div class="eyebrow">MERGE CONFLICTS</div><h2>${esc((d.conflicts||[]).length)} preserved conflict records</h2>${d.conflicts?.length?`<table class="ip-table"><thead><tr><th>Project / module</th><th>Path</th><th>Resolution</th></tr></thead><tbody>${d.conflicts.slice(0,30).map(c=>`<tr><td>${esc(c.project||'')}<br><code>${esc(c.module||'')}</code></td><td><code>${esc(c.path||'(root)')}</code></td><td>${esc(c.resolution||'')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No merge conflicts recorded.</div>'}</div>`;
  $('#adminRecoveryCode')?.addEventListener('click',async()=>{const ok=confirmPhrase('Issue or rotate a recovery code for this Guest Identity?');if(!ok)return;try{const r=await identitiesPost({action:'issue-recovery',guestId:g.guestId,confirmPhrase:ok});$('#adminRecoveryOut').innerHTML=`<div class="identity-code">${esc(r.recoveryCode)}</div><div class="msg">Give this code only after support has verified the recovery request. LOOM stores only its hash.</div>`}catch(e){$('#adminRecoveryOut').textContent=e.message}});
  $('#attachGuest')?.addEventListener('click',async()=>{const uid=$('#attachUserId').value;if(!uid){$('#identityMsg').textContent='Choose a permanent account.';return}const ok=confirmPhrase(`Attach this Guest History to ${uid}? Source history will be preserved.`);if(!ok)return;try{const r=await identitiesPost({action:'attach',guestId:g.guestId,userId:uid,confirmPhrase:ok});renderIdentityDetail(r.detail,identityState.users);await loadIdentities()}catch(e){$('#identityMsg').textContent=e.message}});
  $('#convertGuest')?.addEventListener('click',async()=>{const email=prompt('Email for the new permanent account:','');if(!email)return;const password=prompt('Temporary password (8+ characters). The user can replace it after signing in:','');if(!password)return;const ok=confirmPhrase(`Create a permanent LOOM account for ${email} and attach this Guest History?`);if(!ok)return;try{const r=await identitiesPost({action:'convert',guestId:g.guestId,email,password,confirmPhrase:ok});renderIdentityDetail(r.detail,identityState.users);await loadIdentities()}catch(e){$('#identityMsg').textContent=e.message}});
  $('#mergeGuest')?.addEventListener('click',async()=>{const target=$('#mergeTargetGuest').value;if(!target){$('#identityMsg').textContent='Choose a target Guest Identity.';return}const ok=confirmPhrase(`Merge ${g.guestId} into ${target}? Both source histories remain preserved.`);if(!ok)return;try{const r=await identitiesPost({action:'merge-guests',sourceGuestId:g.guestId,targetGuestId:target,confirmPhrase:ok});selectedGuestId=target;renderIdentityDetail(r.detail,identityState.users);await loadIdentities()}catch(e){$('#identityMsg').textContent=e.message}})
}
async function loadIdentityDetail(guestId){try{const r=await identitiesPost({action:'detail',guestId});identityState.users=r.users||identityState.users;renderIdentityDetail(r.detail,identityState.users)}catch(e){$('#identityDetail').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function renderDb(){const d=dbState?.database||{};$('#dbHost').value=d.host||'';$('#dbPort').value=d.port||3306;$('#dbName').value=d.database||'';$('#dbUser').value=d.username||'';$('#dbPass').value='';$('#dbStatus').innerHTML=`<span class="pill ${d.connected?'':'warn'}">${d.connected?'Connected':'Not connected'}</span><span class="pill ${d.initialized?'':'warn'}">${d.initialized?'Schema initialized':'Schema not initialized'}</span>`;$('#storagePill').textContent=d.initialized?'Storage: SQL permanent':'Storage: durable local'}
function renderIntegrity(i){if(!i){$('#integritySummary').innerHTML='';$('#integrityIssues').textContent='Run a scan to inspect the database.';return}const sum=i.summary||{},issues=i.issues||[];$('#integritySummary').innerHTML=`<span class="pill ${i.healthy?'':'bad'}">${i.healthy?'Healthy':'Needs attention'}</span><span class="pill ${sum.critical?'bad':''}">${sum.critical||0} critical</span><span class="pill ${sum.warnings?'warn':''}">${sum.warnings||0} warnings</span>`;$('#integrityIssues').innerHTML=issues.length?issues.map(x=>`<div style="padding:8px 0;border-bottom:1px solid #e5ece6"><b>${esc(x.severity.toUpperCase())} · ${esc(x.code)}</b><br>${esc(x.message)}${x.repairable?' <span class="pill">safe repair</span>':''}</div>`).join(''):'<b>No integrity problems detected.</b><br>The core LOOM SQL relationships checked by this release are consistent.'}
async function scanIntegrity(){try{const r=await dbPost({action:'integrity-scan'});renderIntegrity(r.integrity);$('#integrityMsg').textContent='Integrity scan complete.';return r.integrity}catch(e){$('#integrityMsg').textContent=e.message;throw e}}
async function loadDb(){try{dbState=await dbPost({action:'status'});renderDb()}catch(e){$('#dbMsg').textContent=e.message}}
async function loadProjects(){const r=await fetch(`../api/projects.php?clientId=${encodeURIComponent(identity.clientId)}&_=${Date.now()}`,{cache:'no-store'}),j=await r.json(),sel=$('#project');projectsState=j.projects||[];sel.innerHTML=projectsState.map(p=>`<option value="${esc(p.slug)}">${esc(p.name)}</option>`).join('');if(!sel.value)throw new Error('No active projects');const requested=new URLSearchParams(location.search).get('project');if(requested&&[...sel.options].some(o=>o.value===requested))sel.value=requested;sel.onchange=async()=>{await loadSettings();if(tab==='users'){selected=null;await loadUsers();$('#userDetail').innerHTML='<div class="empty">Select a user or client profile.</div>'}}}
async function loadSettings(){const project=$('#project').value;state=await post({action:'settings',project});const info=(projectsState||[]).find(x=>x.slug===project);$('#appLink').href=info?.app_url||`../projects/${encodeURIComponent(project)}/app/?project=${encodeURIComponent(project)}`;$('#pegLink').href=`../pegboard/?project=${encodeURIComponent(project)}`;$('#regLink').href=`../registry/?project=${encodeURIComponent(project)}`;renderProjectProfile();renderModuleControl();renderModules()}
function showTab(next){tab=next;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));$('#loomSettingsPanel').classList.toggle('active',tab==='loom');$('#projectSettingsPanel').classList.toggle('active',tab==='project');$('#usersPanel').classList.toggle('active',tab==='users');$('#identitiesPanel').classList.toggle('active',tab==='identities');$('#databasePanel').classList.toggle('active',tab==='database');$('#projectChooser').classList.toggle('hidden',!(tab==='project'||tab==='users'));if(tab==='loom')loadGlobalSettings();if(tab==='project')loadSettings();if(tab==='users')loadUsers();if(tab==='identities')loadIdentities();if(tab==='database')loadDb()}
$('#moduleControlSearch')?.addEventListener('input',renderModuleControl);document.querySelectorAll('.tab').forEach(x=>x.onclick=()=>showTab(x.dataset.tab));$('#userSearch').oninput=renderUserList;$('#userRefresh').onclick=loadUsers;$('#identitySearch').oninput=renderIdentityList;$('#identityRefresh').onclick=loadIdentities;$('#dbSave').onclick=async()=>{try{dbState=await dbPost({action:'configure',config:{host:$('#dbHost').value,port:Number($('#dbPort').value||3306),database:$('#dbName').value,username:$('#dbUser').value,password:$('#dbPass').value}});$('#dbMsg').textContent=dbState.message;renderDb()}catch(e){$('#dbMsg').textContent=e.message}};$('#dbInit').onclick=async()=>{try{dbState=await dbPost({action:'initialize'});$('#dbMsg').textContent=dbState.message;renderDb()}catch(e){$('#dbMsg').textContent=e.message}};$('#dbMigrate').onclick=async()=>{try{dbState=await dbPost({action:'migrate'});$('#dbMsg').textContent=`${dbState.message} ${JSON.stringify(dbState.migrated)}`;renderDb()}catch(e){$('#dbMsg').textContent=e.message}};$('#integrityScan').onclick=scanIntegrity;$('#integrityBackup').onclick=async()=>{try{const r=await dbPost({action:'integrity-backup'});$('#integrityMsg').textContent=`Snapshot ${r.backup.backupId} created on the protected server storage.`}catch(e){$('#integrityMsg').textContent=e.message}};$('#integrityRepair').onclick=async()=>{const confirmText=prompt('Safe Repair will create a database snapshot first and reconcile known identity mappings. Type CONFIRM to continue.','');if(confirmText!=='CONFIRM')return;try{const r=await dbPost({action:'integrity-repair',confirm:'CONFIRM'});$('#integrityMsg').textContent=`Repair complete. Backup: ${r.repair.backup.backupId}. Actions: ${(r.repair.actions||[]).join(', ')||'none needed'}`;renderIntegrity(r.repair.scan)}catch(e){$('#integrityMsg').textContent=e.message}};
(async()=>{try{const st=await post({action:'status',claim:false,project:'green-beans'});LoomIdentity.setPrivilege(identity.clientId,st.privilege);$('#who').textContent=`${identity.userLabel} · ${identity.clientId.slice(0,20)}…`;await loadProjects();await loadGlobalSettings();await loadDb();const requestedTab=new URLSearchParams(location.search).get('tab');if(requestedTab==='project'){showTab('project')} }catch(e){document.body.innerHTML=`<div style="padding:40px;font-family:system-ui"><h1>Admin access failed</h1><p>${esc(e.message)}</p><a href="../home/">Return home</a></div>`}})();
</script><div id="loomShellFooter"></div><script src="../engine/loom-brand.js?v=0.15.11"></script><script src="../engine/identity.js?v=0.15.11"></script><script src="../engine/loom-global-profile.js?v=0.15.11"></script><script src="../engine/loom-shell.js?v=0.15.11"></script><script>(async()=>{if(!window.LoomShell)return;const ident=LoomIdentity.get('loom-admin');await LoomShell.mount({apiBase:'../api',identity:ident,pageTitle:"Admin",links:[{label:'LOOM Home',href:"../home/"}]})})();</script></body></html>